    private void toggleTorch(){if(!cameraReady||camera==null||torchChanging)return;if(!camera.getCameraInfo().hasFlashUnit()){toast(s("no_lamp"));return;}boolean next=!torch;torchChanging=true;final int session=generation;ListenableFuture<Void> change=camera.getCameraControl().enableTorch(next);change.addListener(()->{if(session!=generation)return;try{change.get();torch=next;lampState(torch);pulse(flashButton);}catch(Exception error){failure(error);}finally{torchChanging=false;}},ContextCompat.getMainExecutor(this));}
    private void lampState(boolean on){if(lampLabel!=null){lampLabel.setText(s(on?"on":"off"));lampLabel.setTextColor(on?0xffffd443:WHITE);}if(scannerSkin!=null){scannerSkin.lamp(on);flashButton.setContentDescription(s("flash")+" "+s(on?"on":"off"));return;}if(flashButton instanceof FrameLayout){FrameLayout frame=(FrameLayout)flashButton;frame.removeAllViews();frame.addView(new UiArt.Icon(this,on?"flash":"flashoff",on?0xffffd443:WHITE),new FrameLayout.LayoutParams(dp(26),dp(26),Gravity.CENTER));frame.setContentDescription(s("lamp")+" "+s(on?"on":"off"));frame.setBackground(card(on?0xff997500:0xff073450,0xff001c32,on?0xffffd443:0xff4c7898));}}
    private void changeZoom(float requested){if(!cameraReady||camera==null)return;ZoomState state=camera.getCameraInfo().getZoomState().getValue();if(state==null)return;float low=Math.max(1,state.getMinZoomRatio()),value=Math.max(low,Math.min(Math.max(low,Math.min(3,state.getMaxZoomRatio())),requested));final int session=generation,request=++zoomRequest;frameEpoch++;zoomChanging=true;ListenableFuture<Void> future=camera.getCameraControl().setZoomRatio(value);future.addListener(()->{if(session!=generation||request!=zoomRequest)return;try{future.get();tracker.rescale(value/zoomRatio);zoomRatio=value;zoomView.value(value);}catch(Exception error){if(!(error.getCause() instanceof CameraControl.OperationCanceledException))failure(error);zoomView.value(zoomRatio);}finally{zoomChanging=false;}},ContextCompat.getMainExecutor(this));}
